(6204067, 915638, 61396, '<td valign="top">How colorful. The woman in black brings it to a new level, and the sun flare at the bottom right is a bonus. Others may not appreciate the yellow sky and some of the highlights, but I don''t mind these at all.</td>', 'How colorful. The woman in black brings it to a new level, and the sun flare at the bottom right is a bonus. Others may not appreciate the yellow sky and some of the highlights, but I don''t mind these at all.', '2010-10-29 04:36:35.000000', NULL, 1),
(6204077, 916483, 61396, '<td valign="top">I like how the old and new, metal and wood, bright and deem, orange and blue, stationary and mobile all merge together in this image. The photog presence is a bonus.</td>', 'I like how the old and new, metal and wood, bright and deem, orange and blue, stationary and mobile all merge together in this image. The photog presence is a bonus.', '2010-10-29 04:51:55.000000', NULL, 1),
