(6205125, 916496, 96751, '<td valign="top">First image I clicked on - from the thumbnails.  Simple and gorgeous.</td>', 'First image I clicked on - from the thumbnails.  Simple and gorgeous.', '2010-10-30 15:31:39.000000', NULL, 1),
(6205310, 916416, 96751, '<td valign="top">Except for the tilt, marvelous.</td>', 'Except for the tilt, marvelous.', '2010-10-30 21:28:41.000000', NULL, 1),
(6205311, 916480, 96751, '<td valign="top">I love this.  So classic.</td>', 'I love this.  So classic.', '2010-10-30 21:29:12.000000', NULL, 1),
(6205312, 916362, 96751, '<td valign="top">These colors are so Rothko!</td>', 'These colors are so Rothko!', '2010-10-30 21:29:40.000000', NULL, 1),
(6205313, 916487, 96751, '<td valign="top">Wonderful isolation.  The sheen on the feathers is terrific.</td>', 'Wonderful isolation.  The sheen on the feathers is terrific.', '2010-10-30 21:30:39.000000', NULL, 1),
