(6205317, 916015, 96751, '<td valign="top">Unusual vantage point and great colors.</td>', 'Unusual vantage point and great colors.', '2010-10-30 21:32:06.000000', NULL, 1),
(6205385, 915598, 96751, '<td valign="top">Lovely portrait.</td>', 'Lovely portrait.', '2010-10-31 00:37:44.000000', NULL, 1),
(6205387, 915494, 96751, '<td valign="top">this almost looks like a pinhole image.  Gorgeous.</td>', 'this almost looks like a pinhole image.  Gorgeous.', '2010-10-31 00:38:44.000000', NULL, 1),
(6205389, 916084, 96751, '<td valign="top">LOL!  Looks totally posed.  And something of a diva at that.  Terrific dof and lighting.</td>', 'LOL!  Looks totally posed.  And something of a diva at that.  Terrific dof and lighting.', '2010-10-31 00:39:38.000000', NULL, 1),
(6205391, 916481, 96751, '<td valign="top">This kind of image takes my breath away.  Doesn''t look like midday sun, but a stunning image nonetheless.</td>', 'This kind of image takes my breath away.  Doesn''t look like midday sun, but a stunning image nonetheless.', '2010-10-31 00:40:48.000000', NULL, 1),
(6205393, 916111, 96751, '<td valign="top">This is a great idea, with superb reflection and lighting. But it''s the pose that is the weakest element here - she does NOT look comfortable.</td>', 'This is a great idea, with superb reflection and lighting. But it''s the pose that is the weakest element here - she does NOT look comfortable.', '2010-10-31 00:42:10.000000', NULL, 1),
(6205395, 916297, 96751, '<td valign="top">I love how you can see his feet all tucked up.  Gorgeous bird, perfect capture.</td>', 'I love how you can see his feet all tucked up.  Gorgeous bird, perfect capture.', '2010-10-31 00:42:43.000000', NULL, 1),
(6205396, 915815, 96751, '<td valign="top">I love this.  Great details and bokeh, and a really nice color pallet.</td>', 'I love this.  Great details and bokeh, and a really nice color pallet.', '2010-10-31 00:43:40.000000', NULL, 1),
(6205397, 915595, 96751, '<td valign="top">Gorgeous park.  Incredible colors.</td>', 'Gorgeous park.  Incredible colors.', '2010-10-31 00:44:21.000000', NULL, 1),
