(6209417, 916487, 108069, '<td valign="top">Awesome image and title. I have no idea what it has to do with the challenge, but it''s still noteworthy.</td>', 'Awesome image and title. I have no idea what it has to do with the challenge, but it''s still noteworthy.', '2010-11-02 23:14:29.000000', NULL, 1),
(6209419, 916452, 108069, '<td valign="top">Great landscape shot. Nice scene. Good use of foreground, though maybe just a tad too much. Just me. But size-wise it''s actually competing with the stacks. Still an excellent shot. Nice work.</td>', 'Great landscape shot. Nice scene. Good use of foreground, though maybe just a tad too much. Just me. But size-wise it''s actually competing with the stacks. Still an excellent shot. Nice work.', '2010-11-02 23:17:13.000000', NULL, 1),
