(6209472, 916305, 67697, '<td valign="top">This is better than a low 5 score.  Wonderful capture of textures.</td>', 'This is better than a low 5 score.  Wonderful capture of textures.', '2010-11-03 00:15:26.000000', NULL, 0),
(6209479, 915638, 30982, '<td valign="top">Nicely done!  Congrats on the top ten!</td>', 'Nicely done!  Congrats on the top ten!', '2010-11-03 00:20:05.000000', NULL, 0),
(6209482, 916487, 54645, '<td valign="top">Wow. Such a beautiful creature, you did a wonderful job playing on the human assumption of these birds.</td>', 'Wow. Such a beautiful creature, you did a wonderful job playing on the human assumption of these birds.', '2010-11-03 00:22:05.000000', NULL, 0),
(6209486, 915457, 114285, '<td valign="top">Hey, I just realised this is your first ribbon, congrats, and i  forgot to comment on the photo, whilst in voting, but it was awesome.</td>', 'Hey, I just realised this is your first ribbon, congrats, and i  forgot to comment on the photo, whilst in voting, but it was awesome.', '2010-11-03 00:24:45.000000', NULL, 0),
(6209487, 916498, 54645, '<td valign="top">Bugger, I thought this would crack the top 5. I wish I voted. Deserved another 10</td>', 'Bugger, I thought this would crack the top 5. I wish I voted. Deserved another 10', '2010-11-03 00:25:00.000000', NULL, 0),
(6209497, 916305, 54645, '<td valign="top">Light, textures, shadows, and reflections. You made a mundane scene interesting.</td>', 'Light, textures, shadows, and reflections. You made a mundane scene interesting.', '2010-11-03 00:30:32.000000', NULL, 0),
(6209508, 916163, 30861, '<td valign="top">One of the few high finishers that actually uses the harshness of midday light to advantage. Congrats.</td>', 'One of the few high finishers that actually uses the harshness of midday light to advantage. Congrats.', '2010-11-03 00:38:07.000000', NULL, 0),
(6209512, 916063, 121949, '<td valign="top">just wanted you to know you got my one and only 10 for this challenge. Congradulations again. You are on a role lately.</td>', 'just wanted you to know you got my one and only 10 for this challenge. Congradulations again. You are on a role lately.', '2010-11-03 00:42:22.000000', NULL, 0),
(6209545, 916487, 68504, '<td valign="top">Another one of yours getting a gasp of recognition.  (Platonic). The shafts highlighted to look like the nails of a venerable ancient from the far east.  Ready to rake.</td>', 'Another one of yours getting a gasp of recognition.  (Platonic). The shafts highlighted to look like the nails of a venerable ancient from the far east.  Ready to rake.', '2010-11-03 00:59:40.000000', NULL, 0),
(6209551, 915494, 68504, '<td valign="top">You are in the zone.  Still haven''t the words for your last wonder (dreams).  I can almost feel the hand of God creating this.  I mean I can almost feel the great brush of creation.</td>', 'You are in the zone.  Still haven''t the words for your last wonder (dreams).  I can almost feel the hand of God creating this.  I mean I can almost feel the great brush of creation.', '2010-11-03 01:06:24.000000', NULL, 0),
(6209556, 915933, 68504, '<td valign="top">This is exquisite.</td>', 'This is exquisite.', '2010-11-03 01:12:13.000000', NULL, 0),
(6209561, 916498, 68504, '<td valign="top">Immediate like. And great respect for the method.  (Not everything that moves is gold).</td>', 'Immediate like. And great respect for the method.  (Not everything that moves is gold).', '2010-11-03 01:16:45.000000', NULL, 0),
(6209568, 916498, 122149, '<td valign="top">i gave this a 7. i''m right next to you :)) 40th.</td>', 'i gave this a 7. i''m right next to you :)) 40th.', '2010-11-03 01:21:48.000000', NULL, 0),
(6209579, 915494, 54645, '<td valign="top">Lovely image, I was enthralled by the soft layers of inviting color and motion. Well deserved PH blue.</td>', 'Lovely image, I was enthralled by the soft layers of inviting color and motion. Well deserved PH blue.', '2010-11-03 01:42:36.000000', NULL, 0),
