INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6209640, 916481, 97225, '<td valign="top">Congratulations, and wow! Great shot. Those sure are impressive waves. I like the presence of the poor little bird.</td>', 'Congratulations, and wow! Great shot. Those sure are impressive waves. I like the presence of the poor little bird.', '2010-11-03 02:13:44.000000', NULL, 0),
(6209673, 916391, 67258, '<td valign="top">Under-appreciated - and what the heck is with the 8 votes of 1 &amp; 2?<br/><br/><i>Message edited by author 2010-11-03 03:14:06.</i></td>', 'Under-appreciated - and what the heck is with the 8 votes of 1 & 2?', '2010-11-03 03:13:05.000000', '2010-11-03 03:14:06.000000', 0),
(6209681, 915457, 7889, '<td valign="top">Congratulations on your blue Ben!</td>', 'Congratulations on your blue Ben!', '2010-11-03 03:43:12.000000', NULL, 0),
(6209683, 915457, 108069, '<td valign="top">Congratulations! A blue on your second entry. Outstanding. And you nearly went from last to first. Very well done. Best of luck to you.</td>', 'Congratulations! A blue on your second entry. Outstanding. And you nearly went from last to first. Very well done. Best of luck to you.', '2010-11-03 03:47:52.000000', NULL, 0),
(6209695, 915457, 95634, '<td valign="top">Oh wow! I did not expect that! Thank you all for the great votes!<br/> <br/>I have been receiving the newsletter for a year and a half now and observing all the great photographs...now I have more confidence and I shall submit images more frequently!<br/> <br/>Thanks!<br/> <br/>Ben<br/> <br/>PS. The only editing I performed was to resize the image and resave as jpeg to meet the size requirements of the site.</td>', 'Oh wow! I did not expect that! Thank you all for the great votes! I have been receiving the newsletter for a year and a half now and observing all the great photographs...now I have more confidence and I shall submit images more frequently! Thanks! Ben PS. The only editing I performed was to resize the image and resave as jpeg to meet the size requirements of the site.', '2010-11-03 04:23:58.000000', NULL, 0),
(6209715, 915631, 82112, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by friiskiwi:</b></div><hr/><i> Lovely shot, but aren''t the shadows a little long for the middle of the day? </i></td></tr></table> <br/> <br/>''Yes, but not for the northern US this time of year at 1 in the afternoon!</td>', 'Originally posted by friiskiwi: Lovely shot, but aren''t the shadows a little long for the middle of the day?   ''Yes, but not for the northern US this time of year at 1 in the afternoon!', '2010-11-03 05:42:27.000000', NULL, 0),
(6209738, 915547, 108069, '<td valign="top">This is an excellent photo and it got a 9 from me. I know how difficult this shot is, and the composition and colors are phenomenal. I love the contrast of the stark dead tree vs. the exploding yellow/orange on the right. Congrats on the well deserved great score and finish.</td>', 'This is an excellent photo and it got a 9 from me. I know how difficult this shot is, and the composition and colors are phenomenal. I love the contrast of the stark dead tree vs. the exploding yellow/orange on the right. Congrats on the well deserved great score and finish.', '2010-11-03 06:44:42.000000', NULL, 0),
(6209819, 916481, 114285, '<td valign="top">I was close, in saying you''d be a winner, well done. You have some awesome photos in your collection. You must live in a beautiful part of the world.</td>', 'I was close, in saying you''d be a winner, well done. You have some awesome photos in your collection. You must live in a beautiful part of the world.', '2010-11-03 08:41:06.000000', NULL, 0),
(6209871, 916481, 69008, '<td valign="top">Good photos of this lighthouse never fail to draw a crowd here at DPC, and for good reason. It''s a thrill to go out and face a storm, and you captured the energy with this shot. Well done.</td>', 'Good photos of this lighthouse never fail to draw a crowd here at DPC, and for good reason. It''s a thrill to go out and face a storm, and you captured the energy with this shot. Well done.', '2010-11-03 09:12:50.000000', NULL, 0),
